DROP TABLE IF EXISTS api_raw2;
CREATE TABLE api_raw2 (payload jsonb);
INSERT INTO api_raw2 VALUES
  ('{"status": "paid", "amount_cents": 1250}'),
  ('{"status": "paid", "amount_cents": 800}'),
  ('{"status": "refunded", "amount_cents": 300}'),
  ('{"status": "failed", "amount_cents": 999}');
SELECT payload->>'status' AS status,
       COUNT(*) AS orders,
       ROUND(SUM((payload->>'amount_cents')::numeric) / 100, 2) AS total_eur
FROM api_raw2
GROUP BY 1
ORDER BY 1;
